import Foundation

/// Coordinates commands across workflows. Presentation/capture effects are
/// supplied by AppDelegate, while pending requests and precedence live here.
@MainActor
final class ApplicationCommands {
    enum Command { case area, fullScreen, reopenFinder, scratchpad, toggleRecording }
    struct State {
        var recordingShortcut = false
        var videoRenameBusy = false
        var scratchpadBusy = false
        var screenshotBusy = false
        var finderLookupBusy = false
        var recordingBusy = false
        var stopAvailable = false
    }
    struct Actions {
        var area: () -> Void
        var fullScreen: () -> Void
        var reopenFinder: () -> Void
        var scratchpad: () -> Void
        var startRecording: () -> Void
        var stopRecording: () -> Void
    }
    private let state: () -> State
    private let actions: Actions
    private let schedule: (@escaping () -> Void) -> Void
    private var gate = UserCommandGate()

    init(state: @escaping () -> State, actions: Actions,
         schedule: @escaping (@escaping () -> Void) -> Void = { DispatchQueue.main.async(execute: $0) }) {
        self.state = state
        self.actions = actions
        self.schedule = schedule
    }

    func perform(_ command: Command) {
        switch command {
        case .area, .fullScreen:
            guard canCapture(state()) else { return }
            if command == .area { actions.area() } else { actions.fullScreen() }
        case .reopenFinder:
            let current = state()
            guard canCapture(current), !current.screenshotBusy else { return }
            actions.reopenFinder()
        case .scratchpad:
            requestScratchpad()
        case .toggleRecording:
            toggleRecording()
        }
    }

    private func canCapture(_ current: State) -> Bool {
        !current.recordingShortcut && !current.videoRenameBusy && !current.recordingBusy
            && gate.canStartScreenshot(scratchpadIsBusy: current.scratchpadBusy)
    }

    private func toggleRecording() {
        let current = state()
        guard !current.recordingShortcut else { return }
        // Stop must remain available while another workflow or lookup is busy.
        if current.stopAvailable {
            actions.stopRecording()
            return
        }
        guard !current.videoRenameBusy, !current.screenshotBusy, !current.finderLookupBusy,
              gate.canStartScreenshot(scratchpadIsBusy: current.scratchpadBusy) else { return }
        actions.startRecording()
    }

    private func requestScratchpad() {
        guard gate.beginScratchpadOpenRequest() else { return }
        // A menu command must wait until menu tracking ends. Re-read state
        // when the request runs, and release the gate on every exit path.
        schedule { [weak self] in
            guard let self else { return }
            defer { self.gate.finishScratchpadOpenRequest() }
            let current = self.state()
            guard !current.recordingShortcut, !current.videoRenameBusy,
                  !current.recordingBusy, !current.screenshotBusy else { return }
            self.actions.scratchpad()
        }
    }
}

import AppKit
import CoreGraphics
import ScreenCaptureKit

protocol ScreenshotSoundPlaying {
    func playCaptureSound()
}

extension ScreenshotSoundPlayer: ScreenshotSoundPlaying {}

/// Handles screenshot capture, resizing, encoding and filename generation,
/// and then kicks off the rename/note workflow.
final class ScreenshotService: NSObject {
    enum CaptureMode { case area, fullScreen }
    enum ScreenResolutionError: LocalizedError {
        case missingDisplayID
        var errorDescription: String? { "Unable to determine display ID." }
    }

    struct ScreenSnapshot: Sendable {
        let displayID: CGDirectDisplayID
        let frame: CGRect
        let scale: CGFloat
    }

    private struct PreparedCaptureSave {
        let image: NSImage
        let targetURL: URL
        let currentCounter: Int
    }

    @MainActor
    private struct ShareableContentPrefetch {
        let token: UUID
        let task: Task<SCShareableContent, Error>
        var fetchedAt: Date?
    }

    private let settingsStore: SettingsStore
    private let backupService: BackupService
    private let clipboardService: ClipboardService
    private let soundPlayer: ScreenshotSoundPlaying
    private let areaCapture: () async throws -> CGImage?
    private let workflowPresenter: (ScreenshotWorkflowController) -> Void
    private let errorPresenter: (String, String) -> Void
    private let captureScreen: (CaptureMode) throws -> ScreenSnapshot?
    private let regionCapture: ((CGRect, ScreenSnapshot) async throws -> CGImage)?

    private let fileManager: FileManager
    private let desktopDirectory: URL
    private let capturePersistenceQueue = DispatchQueue(label: "Zoomies.CapturePersistence", qos: .userInitiated)

    private var activeWorkflow: ScreenshotWorkflowController?
    private var isCaptureInProgress = false
    @MainActor private var shareableContentPrefetch: ShareableContentPrefetch?
    private let shareableContentPrefetchTTL: TimeInterval = 2

    init(settingsStore: SettingsStore,
         backupService: BackupService,
         clipboardService: ClipboardService,
         fileManager: FileManager = .default,
         desktopDirectory: URL? = nil,
         soundPlayer: ScreenshotSoundPlaying = ScreenshotSoundPlayer(),
         areaCapture: @escaping () async throws -> CGImage? = { try await NativeAreaCapture.capture() },
         captureScreen: @escaping (CaptureMode) throws -> ScreenSnapshot? = ScreenshotService.currentCaptureScreen,
         regionCapture: ((CGRect, ScreenSnapshot) async throws -> CGImage)? = nil,
         workflowPresenter: @escaping (ScreenshotWorkflowController) -> Void = { $0.start() },
         errorPresenter: @escaping (String, String) -> Void = { AlertPresenter.presentWarning(title: $0, message: $1) }) {
        self.settingsStore = settingsStore
        self.backupService = backupService
        self.clipboardService = clipboardService
        self.soundPlayer = soundPlayer
        self.areaCapture = areaCapture
        self.captureScreen = captureScreen
        self.regionCapture = regionCapture
        self.workflowPresenter = workflowPresenter
        self.errorPresenter = errorPresenter
        self.fileManager = fileManager

        if let desktopDirectory {
            self.desktopDirectory = desktopDirectory
        } else {
            let home = fileManager.homeDirectoryForCurrentUser
            self.desktopDirectory = home.appendingPathComponent("Desktop", isDirectory: true)
        }

        super.init()
    }

    // MARK: - Public API

    func captureArea() {
        if !Thread.isMainThread {
            DispatchQueue.main.async { [weak self] in
                self?.captureArea()
            }
            return
        }

        guard canStartAreaCapture() else {
            return
        }

        performCapture { [self] in
            guard let image = try await areaCapture() else { return nil }
            guard let screen = try await MainActor.run(body: { try self.captureScreen(.area) }) else { return nil }
            return (image, screen.displayID)
        }
    }

    /// Captures the full contents of the display under the mouse.
    func captureFullScreen() {
        if !Thread.isMainThread {
            DispatchQueue.main.async { [weak self] in
                self?.captureFullScreen()
            }
            return
        }

        guard canStartFullScreenCapture() else {
            return
        }
        do {
            guard let screen = try captureScreen(.fullScreen) else { return }
            captureRegion(in: screen.frame, on: screen)
        } catch {
            handleCaptureFailure(error)
        }
    }

    /// Starts the rename/note flow for an already-saved image.
    func beginPostCaptureFlow(forExistingFileAt url: URL, on screen: NSScreen? = nil, escapeKeyDeletesFile: Bool = true) {
        beginPostCaptureFlow(forExistingFileAt: url,
                             initialImage: nil,
                             initialFilePersistence: nil,
                             initialScreenshotCounter: nil,
                             on: screen,
                             escapeKeyDeletesFile: escapeKeyDeletesFile)
    }

                                 exceptingWindows: [])

    return try await withCheckedThrowingContinuation { continuation in
        SCScreenshotManager.captureImage(contentFilter: filter, configuration: configuration) { image, error in
            if let error {
                continuation.resume(throwing: error)
            } else if let image {
                continuation.resume(returning: image)
            } else {
                continuation.resume(throwing: NSError(domain: "ScreenshotService",
                                                      code: -5,
                                                      userInfo: [NSLocalizedDescriptionKey: "No image captured."]))
            }
        }
    }
}

// MARK: - Error handling

private func handleCaptureFailure(_ error: Error) {
    let nsError = error as NSError
    // macOS already owns the native Screen Recording permission flow.
    // When the user declines capture authorization, avoid stacking our own alert on top.
    if ScreenshotServiceCoreLogic.shouldSuppressCaptureFailureAlert(nsError) {
        return
    }
    presentError(title: "Screenshot failed", message: nsError.localizedDescription)
}

// MARK: - Helpers

static func currentCaptureScreen(_ mode: CaptureMode) throws -> ScreenSnapshot? {
    let menuBarScreen = mode == .fullScreen
        ? NSScreen.screens.first(where: { $0.displayID == CGMainDisplayID() }) : nil
    let screen = NSScreen.screens.first(where: { $0.frame.contains(NSEvent.mouseLocation) })
        ?? menuBarScreen
        ?? NSScreen.main ?? NSScreen.screens.first
    guard let screen else { return nil }
    guard let displayID = screen.displayID else {
        if mode == .fullScreen { throw ScreenResolutionError.missingDisplayID }
        return nil
    }
    return ScreenSnapshot(displayID: displayID, frame: screen.frame, scale: screen.backingScaleFactor)
}

private func screenForDisplayID(_ displayID: CGDirectDisplayID?) -> NSScreen? {
    guard let displayID else {
        return nil
    }
    return NSScreen.screens.first(where: { $0.displayID == displayID })

import AppKit

@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate {
    private var statusItemController: TrayService!
    private var settingsWindowController: SettingsWindowController?

    private let settingsStore = SettingsStore()
    private var hotKeyService: HotKeyService!
    private var screenshotService: ScreenshotService!
    private var recordingService: ScreenRecordingService!
    private var videoRenameController: VideoRenameWorkflowController?
    private var clipboardService: ClipboardService!
    private var scratchpadService: ScratchpadService!
    private var backupService: BackupService!
    private let screenshotSoundPlayer = ScreenshotSoundPlayer()
    private let finderSelectionLookup = FinderSelectionLookupCoordinator()

    private lazy var commands = ApplicationCommands(state: { [unowned self] in
        ApplicationCommands.State(
            recordingShortcut: settingsWindowController?.isRecordingAnyShortcut == true,
            videoRenameBusy: isVideoRenameBusy,
            scratchpadBusy: scratchpadService.isBusyForUserCommands,
            screenshotBusy: screenshotService.isBusyForUserCommands,
            finderLookupBusy: finderSelectionLookup.isLookupInProgress,
            recordingBusy: recordingService.isBusyForUserCommands,
            stopAvailable: recordingService.isStopAvailable)
    }, actions: .init(
        area: { [unowned self] in screenshotService.captureArea() },
        fullScreen: { [unowned self] in screenshotService.captureFullScreen() },
        reopenFinder: { [unowned self] in
            finderSelectionLookup.requestSelection { [weak self] in self?.handleFinderSelectionResult($0) }
        },
        scratchpad: { [unowned self] in scratchpadService.open() },
        startRecording: { [unowned self] in recordingService.start(frameRate: settingsStore.settings.recordingFrameRate) },
        stopRecording: { [unowned self] in recordingService.stop() }))

    func applicationDidFinishLaunching(_ notification: Notification) {
        settingsStore.load()

        backupService = BackupService()
        clipboardService = ClipboardService()

        // Intentional: clipboard cache is only needed to keep Cmd+Delete paste working
        // within the current app session. Purging on launch prevents stale cached files
        // from accumulating indefinitely across launches.
        backupService.purgeAllBackups()
        clipboardService.purgeAllCachedFiles()

        screenshotService = ScreenshotService(settingsStore: settingsStore,
                                             backupService: backupService,
                                             clipboardService: clipboardService,
                                             soundPlayer: screenshotSoundPlayer)
        screenshotSoundPlayer.prewarmCaptureSound()
        scratchpadService = ScratchpadService(clipboardService: clipboardService)
        hotKeyService = HotKeyService()
        recordingService = ScreenRecordingService()
        recordingService.onUpdate = { [weak self] in
            self?.refreshRecordingUI()
        }
        recordingService.onRecordingSaved = { [weak self] url in
            self?.openVideoRename(for: url)
        }

        statusItemController = TrayService(onShowSettings: { [weak self] in
            self?.showSettings()
        })
        refreshRecordingUI()

        registerHotKeys()
        showWelcomeInfo()
        presentSettingsRepairNoticeIfNeeded()
    }

    private func showWelcomeInfo() {
        DispatchQueue.main.async {
            // Keep the welcome and shortcut setup tips visible on launch.
            let alert = NSAlert()
            alert.alertStyle = .informational
            alert.messageText = "Welcome to Zoomies"
            alert.informativeText = """
            Hello! Please take 30 seconds to get set up and give Zoomies a proper chance.

            For the best experience, I recommend swapping your screenshot shortcuts: use Cmd+Shift for Zoomies and Option+Shift for macOS screenshots.

            First, move the macOS shortcuts to Option+Shift in System Settings → Keyboard → Keyboard Shortcuts → Screenshots. Then set Zoomies to Cmd+Shift from the Zoomies menu-bar icon → Settings → Shortcuts.

            Default shortcuts:
            • Option+Shift+4 → Area capture
            • Option+Shift+3 → Full-screen capture
            • Option+Shift+2 → Edit or rename an image selected in Finder
            • Option+Shift+1 → Create a scratchpad note
            • Option+Shift+5 → Start/stop screen recording (macOS 15+)

            On your first capture, allow Screen Recording when macOS asks. You can also enable it later in System Settings → Privacy & Security → Screen Recording.
            """
            alert.addButton(withTitle: "OK")
            alert.runModal()
        }
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        return false
    }

    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        guard recordingService.isBusyForUserCommands else {
            return .terminateNow
        }
        // Request stop and let the recording finalize before quitting.
        // The service bounds the wait so termination never hangs forever.
        recordingService.stopForAppTermination {
            NSApp.reply(toApplicationShouldTerminate: true)
        }
        return .terminateLater
    }

    private func presentSettingsRepairNoticeIfNeeded() {
        guard settingsStore.didRepairInvalidSettingsOnLastLoad else { return }
        DispatchQueue.main.async {
            AlertPresenter.presentWarning(
                title: "Some settings were repaired",
                message: "Zoomies found invalid values in its saved settings and restored those to their defaults. Your other settings were left unchanged."
            )
        }
    }

    private func registerHotKeys() {
        hotKeyService.onRegistrationFailures = { failures in
            DispatchQueue.main.async {
                AlertPresenter.presentWarning(
                    title: "Some shortcuts couldn't be registered",
                    message: """
                    These combos are already taken by macOS or another app, so they won't work:

                    \(failures.joined(separator: "\n"))

                    Free them up in System Settings → Keyboard → Keyboard Shortcuts, or pick a different combo in Zoomies Settings. You can always open the Scratchpad from the menu-bar icon.
                    """
                )
            }
        }
        hotKeyService.registerShortcuts(settings: settingsStore.settings,
                                        areaHandler: { [weak self] in self?.triggerAreaScreenshot() },
                                        fullHandler: { [weak self] in self?.triggerFullScreenshot() },
                                        reopenFinderSelectionHandler: { [weak self] in self?.triggerReopenFinderSelection() },
                                        openScratchpadHandler: { [weak self] in self?.triggerOpenScratchpad() },
                                        toggleRecordingHandler: { [weak self] in self?.toggleRecording() })
    }

    private func refreshRecordingUI() {
        statusItemController.updateRecording(state: recordingService.state,
                                             elapsed: recordingService.elapsed)
    }

    /// Single entry point for the recording menu command and shortcut.
    /// A stop request is honored before any busy-state checks so Stop stays
    /// available while recording; startup is rejected while screenshot,
    /// note, Finder-reopen, or video-rename work is active or opening.
    private func toggleRecording() {
        commands.perform(.toggleRecording)
    }

    /// Opens the rename panel for a successfully saved recording. The
    /// controller is retained until the flow finishes, keeping Zoomies busy
    /// for other operations meanwhile.
    private func openVideoRename(for url: URL) {
        guard videoRenameController == nil else { return }
        let controller = VideoRenameWorkflowController(
            fileURL: url,
            settingsStore: settingsStore,
            clipboardService: clipboardService
        )
        controller.onFinish = { [weak self] in
            self?.videoRenameController = nil
        }
        videoRenameController = controller
        controller.start()
    }

    private var isVideoRenameBusy: Bool {
        videoRenameController?.isBusyForUserCommands == true
    }

    private func triggerAreaScreenshot() { commands.perform(.area) }

    private func triggerFullScreenshot() { commands.perform(.fullScreen) }

    private func triggerReopenFinderSelection() { commands.perform(.reopenFinder) }

    private func handleFinderSelectionResult(_ result: Result<FinderSelectionService.Selection, Error>) {
        switch FinderReopenLogic.resolve(result) {
        case .open(let url):
            screenshotService.beginPostCaptureFlow(forExistingFileAt: url, on: nil, escapeKeyDeletesFile: false)
        case .warning(let title, let message, let settingsURL):
            if let settingsURL {
                AlertPresenter.presentWarningWithSettingsButton(title: title, message: message, settingsURL: settingsURL)
            } else {
                presentError(title: title, message: message)
            }
        }
    }

    private func triggerOpenScratchpad() { commands.perform(.scratchpad) }

    private func showSettings() {
        // Menu-item actions run while NSMenu is tracking; defer opening the window
        // to the next runloop turn so the menu can dismiss first.
        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }
            let settingsWindowController = self.settingsWindowControllerOrCreate()
            NSApp.setActivationPolicy(.regular)
            NSApp.activate(ignoringOtherApps: true)
            settingsWindowController.showWindow(nil)
            settingsWindowController.window?.makeKeyAndOrderFront(nil)
        }
    }

    private func settingsWindowControllerOrCreate() -> SettingsWindowController {
        if let existing = settingsWindowController {
            return existing
        }
        let created = SettingsWindowController(settingsStore: settingsStore, hotKeyService: hotKeyService)
        settingsWindowController = created
        return created
    }

    private func presentError(title: String, message: String) {
        AlertPresenter.presentWarning(title: title, message: message)
    }
}

